import heapq
from itertools import combinations


def _temporal(minimum, exact):
    def solve(data):
        required = data.get("required", [])
        full = (1 << len(required)) - 1
        visited_at_node = [0] * data["n"]
        for i, node in enumerate(required):
            visited_at_node[node] |= 1 << i
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        initial = (data["source"], full ^ visited_at_node[data["source"]],
                   data["coupons"], data["start"])
        queue = [(data["start"], initial)]
        best = {initial: data["start"]}
        while queue:
            time, state = heapq.heappop(queue)
            if best.get(state) != time:
                continue
            node, missing, remaining, _ = state
            if node == data["target"] and missing == 0 and (not exact or remaining == 0):
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(minimum, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                for duration, after in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = (edge["v"], missing & ~visited_at_node[edge["v"]], after, arrival)
                    if arrival < best.get(nxt, float("inf")):
                        best[nxt] = arrival
                        heapq.heappush(queue, (arrival, nxt))
        return {"arrival": None}
    return solve


def _ledger(data):
    mode = data["rounding"]

    def rounded(num):
        if mode == "half_up":
            return (num + 5000) // 10000
        return num // 10000

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    names = sorted(packages, reverse=True)
    best_vector = None
    best_install = None

    def visit(assign):
        nonlocal best_vector, best_install
        # Propagate constraints to closure, branching when a package has alternatives.
        pending = [(n, lo, hi) for n, (lo, hi) in data["roots"].items()]
        constraints = {}
        graph = {}
        while pending:
            name, lo, hi = pending.pop()
            constraints.setdefault(name, []).append((lo, hi))
            row_version = assign.get(name)
            if row_version is None:
                continue
            if not all(a <= row_version <= b for a, b in constraints[name]):
                return
            row = next(r for r in packages[name] if r["version"] == row_version)
            deps = [d for d in row.get("deps", [])
                    if not d.get("feature") or d.get("feature") in features]
            graph[name] = [d["name"] for d in deps]
            pending.extend((d["name"], d["min"], d["max"]) for d in deps)
        # Add constraints introduced by already selected assigned rows on every pass.
        for name, version in assign.items():
            if name in constraints:
                continue
        unresolved = [n for n in constraints if n not in assign]
        if unresolved:
            name = unresolved[0]
            intervals = constraints[name]
            rows = [r for r in packages[name]
                    if all(lo <= r["version"] <= hi for lo, hi in intervals)
                    and r["version"] not in blocked.get(name, [])
                    and (name not in pins or r["version"] == pins[name])]
            if name in assign:
                rows = [r for r in rows if r["version"] == assign[name]]
            for row in rows:
                new = dict(assign)
                new[name] = row["version"]
                visit(new)
            return
        # Ensure assigned packages that are active meet all constraints and cycle-check.
        if any(name not in assign for name in constraints):
            return
        # Reconstruct closure graph; constraints gathering above used assignments.
        graph = {}
        for name in constraints:
            row = next(r for r in packages[name] if r["version"] == assign[name])
            graph[name] = [d["name"] for d in row.get("deps", [])
                           if not d.get("feature") or d.get("feature") in features]
        active, done = set(), set()
        def acyclic(node):
            if node in active:
                return False
            if node in done:
                return True
            active.add(node)
            if any(not acyclic(dep) for dep in graph.get(node, [])):
                return False
            active.remove(node)
            done.add(node)
            return True
        if not all(acyclic(n) for n in graph):
            return
        vector = tuple(assign.get(n, -1) for n in names)
        if best_vector is None or vector < best_vector:
            best_vector, best_install = vector, {n: assign[n] for n in constraints}

    # Search from roots; assignments are expanded lazily.
    visit({})
    if best_install is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_install}


def _quotas(data):
    jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
    k = data["k"]
    required = set(data.get("mandatory", []))
    if not required.issubset({j["id"] for j in jobs}):
        return {"error": "impossible"}
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = [j["id"] for j in subset]
        if not required.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        if any(ordered[i]["start"] < ordered[i-1]["end"]
               for i in range(1, len(ordered))):
            continue
        selected = sorted(ids)
        value = sum(j["value"] for j in subset)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": _temporal(2, False),
    "component_02": _temporal(2, True),
    "component_03": _temporal(1, False),
    "component_04": _temporal(1, True),
    "component_05": _temporal(2, False),
    "component_06": _ledger,
    "component_07": _resolver,
    "component_08": _quotas,
}
